SELECT ?zName ?ptClass ?ts WHERE {
  ?z a brick:Zone ; brick:hasName ?zName .
  ?z brick:hasPoint ?pt .
  ?pt ref:hasTimeseriesId ?ts .
  ?pt brick:instance_of ?ptClass .
}

SELECT ?p WHERE {
  ?s brick:hasName ?n .
  FILTER(str(?n) LIKE "%Perimeter%")
  ?s a ?p .
}

SELECT ?s ?p ?o WHERE {
  ?s a ?p .
  FILTER(str(?p) LIKE "%Zone%")
  LIMIT 200
}

